head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > M > getDisplayFormat]<br/>컴포넌트의 displayFormat 속성값을 반환합니다.",
    "validation" : [
        "컴포넌트의 displayFormat 속성값을 반환합니다.",
        "displayFormat 속성을 설정하지 않은 경우 ''(Empty String)이 반환됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



scwin.get_displayFormat = function(target) {   
    let rtn = '';
    rtn = target.getDisplayFormat();

     wf_body_bottom.getObj("scwin").setReturnValue("getDisplayFormat : " + rtn);   
}



 // 사용자 정의 함수
 scwin.fn_dpformatter = function(val) {
    return "language -> " + val;
 };



// target1
scwin.btn_setDisplayFormat1_onclick = function (e) {
    target1.setDisplayFormat("#:##-##");
    target1.setValue("langkoKR");
    // target1.focus();
};

scwin.btn_getDisplayFormat1_onclick = function (e) {
    scwin.get_displayFormat(target1);
};

// target2
scwin.btn_setDisplayFormat2_onclick = function (e) {

    target2.setDisplayFormat("₩ #,###.#0[floor] won");
    target2.setValue("-1234.5678");
    // target2.focus();
};

scwin.btn_getDisplayFormat2_onclick = function (e) {
    scwin.get_displayFormat(target2);
};

// target3
scwin.btn_setDisplayFormat3_onclick = function (e) {

    target3.setDisplayFormat("dd/MM/yyyy (E)");
    target3.setValue("20080501");
    // target3.focus();
};

scwin.btn_getDisplayFormat3_onclick = function (e) {
    scwin.get_displayFormat(target3);
};

// target4
scwin.btn_setDisplayFormat4_onclick = function (e) {
    target4.setDisplayFormat("HH:mm:ss");
    target4.setValue("121521");
    // target4.focus();
};

scwin.btn_getDisplayFormat4_onclick = function (e) {
    scwin.get_displayFormat(target4);
};

// target5
scwin.btn_setDisplayFormat5_onclick = function (e) {
    target5.setDisplayFormat("#:##-##");
    target5.setValue("langkoKR");
    // target1.focus();
};

scwin.btn_getDisplayFormat5_onclick = function (e) {
    scwin.get_displayFormat(target5);
};

// target6
scwin.btn_setDisplayFormat6_onclick = function (e) {
    target6.setDisplayFormat("0:00-00");
    target6.setValue("langkoKR");
    // target1.focus();
};

scwin.btn_getDisplayFormat6_onclick = function (e) {
    scwin.get_displayFormat(target6);
};

// target7 - displayFormat 미설정, 기대값=''
scwin.btn_getDisplayFormat7_onclick = function (e) {
    scwin.get_displayFormat(target7);
};


scwin.btn_setAll_onclick = function (e) {
    // target7은 displayFormat 미설정 검증용이므로 setAll에서 제외
    for (var i = 1; i < 7; i ++)
        eval("scwin.btn_setDisplayFormat"+i+"_onclick()");
}

scwin.btn_getAll_onclick = function (e) {
    for (var i = 1; i < 8; i ++) {
        eval("scwin.btn_getDisplayFormat"+i+"_onclick()");
    }
};
